const items = $input.all();
const data = $getWorkflowStaticData('global');
if (!data.taskState) data.taskState = {};

const PERIODIC_HOURS = { daily: 24, every_8_hours: 8, multiple_times: 4 };
const ONETIME_LEAD_HOURS = { '1_week_before': 168, '1_hour_before': 1, '2_hours_before': 2 };

const now = Date.now();
const out = [];

for (const item of items) {
  const task = item.json;
  if (!task.id) continue;
  const desc = task.description || task.text_content || '';
  const m = desc.match(/\[BOTMETA\]([\s\S]*?)\[\/BOTMETA\]/);
  if (!m) continue;
  let meta;
  try { meta = JSON.parse(m[1]); } catch (e) { continue; }
  if (!meta.reminder_admin && !meta.reminder_assignee) continue;

  const dueMs = task.due_date ? Number(task.due_date) : null;
  const isClosed = task.status && task.status.type === 'closed';
  if (isClosed) continue;
  const overdue = dueMs ? now > dueMs : false;
  const dueText = dueMs ? (new Date(dueMs).toDateString() + ' ' + new Date(dueMs).toLocaleTimeString()) : 'no due date';
  const priorityName = (task.priority && task.priority.priority) ? task.priority.priority : 'normal';

  if (!data.taskState[task.id]) data.taskState[task.id] = {};
  const state = data.taskState[task.id];

  function periodicDue(cadence, lastTsKey) {
    const hrs = PERIODIC_HOURS[cadence];
    if (!hrs) return false;
    const last = state[lastTsKey] || 0;
    if (now - last >= hrs * 3600 * 1000) { state[lastTsKey] = now; return true; }
    return false;
  }
  function customDue(minutes, lastTsKey) {
    const ms = Number(minutes) * 60 * 1000;
    if (!ms || ms <= 0) return false;
    const last = state[lastTsKey] || 0;
    if (now - last >= ms) { state[lastTsKey] = now; return true; }
    return false;
  }
  function onetimeDue(cadence, sentKey) {
    const leadHrs = ONETIME_LEAD_HOURS[cadence];
    if (!leadHrs || !dueMs) return false;
    if (state[sentKey]) return false;
    const windowStart = dueMs - leadHrs * 3600 * 1000;
    if (now >= windowStart && now < dueMs) { state[sentKey] = true; return true; }
    return false;
  }

  if (meta.reminder_admin) {
    let adminDue = false;
    if (meta.reminder_admin === 'custom' && meta.reminder_admin_minutes) adminDue = customDue(meta.reminder_admin_minutes, 'last_admin_ts');
          else if (PERIODIC_HOURS[meta.reminder_admin]) adminDue = periodicDue(meta.reminder_admin, 'last_admin_ts');
          else adminDue = onetimeDue(meta.reminder_admin, 'admin_onetime_sent');
    if (adminDue) {
      out.push({ json: { whatsapp_payload: {
        messaging_product: 'whatsapp', to: '2547XXXXXXXX', type: 'text',
        text: { body: 'Reminder: Task "' + task.name + '" is due ' + dueText + '. Priority: ' + priorityName + '.' + (overdue ? ' This task is now OVERDUE.' : '') }
      } } });
    }
  }

  if (meta.reminder_assignee && meta.assignee_whatsapp && meta.assignee_whatsapp !== '2547XXXXXXXX') {
    let assigneeDue = false;
    let isOverdueCheck = false;
    if (overdue) {
      const lastOverdue = state.last_overdue_ts || 0;
      if (now - lastOverdue >= 4 * 3600 * 1000) { state.last_overdue_ts = now; assigneeDue = true; isOverdueCheck = true; }
    } else {
      if (meta.reminder_assignee === 'custom' && meta.reminder_assignee_minutes) assigneeDue = customDue(meta.reminder_assignee_minutes, 'last_assignee_ts');
          else if (PERIODIC_HOURS[meta.reminder_assignee]) assigneeDue = periodicDue(meta.reminder_assignee, 'last_assignee_ts');
          else assigneeDue = onetimeDue(meta.reminder_assignee, 'assignee_onetime_sent');
    }
    if (assigneeDue) {
      if (isOverdueCheck) {
        out.push({ json: { whatsapp_payload: {
          messaging_product: 'whatsapp', to: meta.assignee_whatsapp, type: 'interactive',
          interactive: { type: 'button', body: { text: 'Have you completed "' + task.name + '"? It was due ' + dueText + '.' },
            action: { buttons: [
              { type: 'reply', reply: { id: 'done_yes_' + task.id, title: 'Yes' } },
              { type: 'reply', reply: { id: 'done_no_' + task.id, title: 'Not yet' } }
            ] } }
        } } });
      } else {
        out.push({ json: { whatsapp_payload: {
          messaging_product: 'whatsapp', to: meta.assignee_whatsapp, type: 'text',
          text: { body: 'Reminder: Task "' + task.name + '" is due ' + dueText + '. Priority: ' + priorityName + '.' }
        } } });
      }
    }
  }
}

return out;
